files.scripts/backup.sh:
#!/usr/bin/env bash
set -euo pipefail

log_dump_0() {
  echo "[$(date +%H:%M)] dump step 0: $*"
}

log_ship_1() {
  echo "[$(date +%H:%M)] ship step 1: $*"
}

log_dump_2() {
  echo "[$(date +%H:%M)] dump step 2: $*"
}


# retention: BACKUP_KEEP_DAYS (see env.sh)
find /var/bk -mtime +"$BACKUP_KEEP_DAYS" -delete

